ALTER TABLE `gram`.`risk_findings` ADD COLUMN `shadow` UInt8 DEFAULT 0 COMMENT 'Set to 1 on findings the LLM analyzer produced while the organization ran the shadow risk engine mode, recorded to compare the model with the legacy engines per message and never enforced. Every user-facing read path filters shadow = 0, so shadow rows are hidden from Risk Events, the overview, signals, the Watchdog and reveal by default. 0 on every enforcing finding and on rows written before this column existed.';
